IF (SELECT COUNT(*) FROM Meets WHERE (Name = '2007 Amherst Comet Relays' AND Date = '2007-04-21') OR (Name = '2010 Suburban League Championships' AND Date = '2010-05-15') OR (Name = '2007 Wolverine Invitational' AND Date = '2007-03-30') OR (Name = '2007 Kimberly Relays' AND Date = '2007-04-28') OR (Name = '2006 Amherst Comet Relays' AND Date = '2006-04-22') OR (Name = '2006 Suburban League Championships' AND Date = '2006-05-13') OR (Name = '2006 Kimberly Relays' AND Date = '2006-04-29') OR (Name = '2009 Suburban League Championships' AND Date = '2009-05-16') OR (Name = '2010 Kimberly Relays' AND Date = '2010-04-03') OR (Name = '2007 Suburban League Championships' AND Date = '2007-05-12') OR (Name = '2007 Division I District Track Meet' AND Date = '2007-05-18')) <> 11 THROW 50011, 'Meet Ids do not match this database', 1;
